```java
public static int fee(int minutes) {
    if (minutes <= 30) {
        return 0;
    }
    int hours = (minutes + 59) / 60;
    int cost = hours * 3;
    if (cost > 27) {
        cost = 27;
    }
    return cost;
}
```

```java
public static int longestStay(int budget) {
    for (int m = 1440; m >= 0; m--) {
        if (fee(m) <= budget) {
            return m;
        }
    }
    return 0;
}
```

```java
public class ScoreKeeper {
    private static int totalScores = 0;
    private String name;
    private int sum;
    private int count;
    private int best;
    public ScoreKeeper(String name) {
        this.name = name;
        best = -1;
    }
    public void addScore(int s) {
        sum += s;
        count++;
        totalScores++;
        if (s > best) {
            best = s;
        }
    }
    public double getAverage() {
        if (count == 0) {
            return 0.0;
        }
        return (double) sum / count;
    }
    public int getBest() {
        return best;
    }
    public static int getTotalScores() {
        return totalScores;
    }
}
```

```java
public int totalTime(String artist) {
    int total = 0;
    for (Song s : songs) {
        if (s.getArtist().equals(artist)) {
            total += s.getSeconds();
        }
    }
    return total;
}
```

```java
public int removeShort(int min) {
    int removed = 0;
    for (int i = songs.size() - 1; i >= 0; i--) {
        if (songs.get(i).getSeconds() < min) {
            songs.remove(i);
            removed++;
        }
    }
    return removed;
}
```

```java
public int emptyInRow(int row) {
    int count = 0;
    for (int c = 0; c < seats[row].length; c++) {
        if (seats[row][c] == 0) {
            count++;
        }
    }
    return count;
}
```

```java
public int findBlock(int k) {
    for (int r = 0; r < seats.length; r++) {
        int run = 0;
        for (int c = 0; c < seats[r].length; c++) {
            if (seats[r][c] == 0) {
                run++;
            } else {
                run = 0;
            }
            if (run >= k) {
                return r;
            }
        }
    }
    return -1;
}
```
